<header class="admin-top"><div><p>Operations</p><h1>Error Center</h1></div><span class="status"><?=count(array_filter($errors,fn($e)=>($e['status']??'open')==='open'))?> OPEN</span></header>
<section class="admin-panel"><table class="admin-table"><thead><tr><th>Time</th><th>Code</th><th>Message</th><th>Context</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach($errors as $e):?><tr><td><?=pm_e($e['occurred_at']??$e['created_at']??'')?></td><td><strong><?=pm_e($e['code']??'ERROR')?></strong></td><td class="error-text"><?=pm_e($e['message']??'')?></td><td><small><?=pm_e(json_encode($e['context']??[],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></small></td><td><span class="status <?=pm_e($e['status']??'open')?>"><?=pm_e(strtoupper($e['status']??'open'))?></span></td><td><?php if(($e['status']??'open')==='open'):?><button data-resolve-error="<?=pm_e($e['id'])?>">Resolve</button><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$errors):?><div class="admin-empty">No system errors recorded.</div><?php endif;?></section>
